import {COLORS,LETTERS,CUE_COLORS,escapeHTML as esc,time,clamp} from './core.js';
import {PANEL_NAMES} from './layout.js';
export const icons={play:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m8 5 11 7-11 7Z" fill="currentColor" stroke="none"/></svg>',pause:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 5v14M17 5v14" stroke-width="5"/></svg>',headphones:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 14v-3a8 8 0 0 1 16 0v3M4 12h3v8H4a2 2 0 0 1-2-2v-4a2 2 0 0 1 2-2Zm16 0h-3v8h3a2 2 0 0 0 2-2v-4a2 2 0 0 0-2-2Z"/></svg>',folder:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 7h7l2 3h9v10H3V4h7l2 3h8"/></svg>',grip:'⠿',arrow:'↥'};
export function panel(id,body,tools=''){return `<section class="panel" data-panel="${id}" style="--accent:${id.startsWith('deck')?COLORS[Number(id.slice(4))]:'var(--cyan)'}"><header class="panel-header panel-drag"><span class="grip" aria-hidden="true">${icons.grip}</span><h2>${PANEL_NAMES[id]}</h2><div class="header-spacer"></div>${tools}<button class="panel-hide" data-panel-toggle="${id}" aria-label="${PANEL_NAMES[id]}を隠す">×</button></header><div class="panel-body">${body}</div><div class="resize-handle" aria-label="パネルのサイズ変更"></div></section>`;}
export function deckMarkup(i,s,t,landscape=false){const d=s.decks[i],letter=LETTERS[i],bpm=t?.samplePending?'未解析':t?Number(t.bpm*d.rate).toFixed(1):'—';const parts={
track:`<div class="deck-track"><div class="deck-identity"><span class="deck-letter">${letter}</span><div><h3 title="${esc(t?.name||'')}">${esc(t?.name||'音源をロード')}</h3><p>${esc(t?.artist||'ライブラリからドロップ')}</p></div></div><button class="deck-load" data-action="load-selected" data-deck="${i}" title="選択した音源をDECK ${letter}へロード" aria-label="DECK ${letter}へロード">${icons.arrow}</button></div>`,
data:`<div class="deck-data"><span class="bpm-display" data-bpm="${i}">${bpm}</span><button data-action="grid" data-deck="${i}" class="bpm-label" title="BPMとグリッドを編集">BPM${t?.demo?'':' ≈'}</button><span class="key-display">${esc(t?.key||'—')}</span><span class="header-spacer"></span><span class="track-duration mono">${t?.samplePending?'未解析':t?time(t.duration):'--:--'}</span><button class="deck-lock ${d.locked?'active':''}" data-action="lock" data-deck="${i}" aria-pressed="${d.locked}" title="演奏中の音源ロードをロック">${d.locked?'LOCK':'OPEN'}</button></div>`,
overview:`<canvas class="overview" data-overview="${i}" aria-label="DECK ${letter}の波形。クリックで再生位置を変更" role="slider" tabindex="0" aria-valuemin="0" aria-valuemax="${t?.duration||0}" aria-valuenow="${d.position}"></canvas>`,
options:`<div class="deck-options"><button data-action="toggle" data-param="keyLock" data-deck="${i}" data-map="deck.${i}.keyLock" class="${d.keyLock?'active':''}" aria-pressed="${d.keyLock}" title="グラニュラー方式のキー固定（試験的）">KEY LOCK</button><button data-action="toggle" data-param="quantize" data-deck="${i}" class="${d.quantize?'active':''}" aria-pressed="${d.quantize}">QUANTIZE</button><button data-action="toggle" data-param="slip" data-deck="${i}" data-map="deck.${i}.slip" class="${d.slip?'active':''}" aria-pressed="${d.slip}">SLIP</button><button data-action="toggle" data-param="reverse" data-deck="${i}" data-map="deck.${i}.reverse" class="${d.reverse?'active':''}" aria-pressed="${d.reverse}">REV</button></div>`,
loop:`<div class="loop-row"><span>LOOP</span><button data-action="loop-half" data-deck="${i}" aria-label="ループ長を半分">½</button><button data-action="loop" data-deck="${i}" data-map="deck.${i}.loop" class="loop-toggle ${d.loop.enabled?'active':''}" aria-pressed="${d.loop.enabled}">${d.loopBeats} BEATS</button><button data-action="loop-double" data-deck="${i}" aria-label="ループ長を2倍">×2</button><button data-action="loop-in" data-deck="${i}">IN</button><button data-action="loop-out" data-deck="${i}">OUT</button><button data-action="jump" data-deck="${i}" data-beats="-${d.loopBeats}" aria-label="${d.loopBeats}拍戻る">«</button><button data-action="jump" data-deck="${i}" data-beats="${d.loopBeats}" aria-label="${d.loopBeats}拍進む">»</button></div>`,
padTabs:`<div class="pad-tabs" role="group" aria-label="パッドモード">${[['cue','HOT CUE'],['roll','LOOP ROLL'],['jump','BEAT JUMP']].map(([m,label])=>`<button data-action="pad-mode" data-deck="${i}" data-mode="${m}" class="${d.padMode===m?'active':''}" aria-pressed="${d.padMode===m}">${label}</button>`).join('')}<span class="header-spacer"></span><span title="Shift＋クリックでキューを削除">SHIFT = DELETE</span><button class="touch-only cue-delete" data-action="cue-delete" aria-pressed="false">キュー削除</button></div>`,
pads:`<div class="cue-pads">${Array.from({length:8},(_,j)=>{const val=t?.cues?.[j],detail=t?.cueDetails?.[j],roll=[.125,.25,.5,1,2,4,8,16][j],jump=[-32,-16,-8,-4,4,8,16,32][j];return `<button data-pad="${j}" data-deck="${i}" data-map="deck.${i}.hotcue${j}" class="cue-pad ${d.padMode==='cue'&&val!=null?'set':''}" title="${esc(detail?.name||'')}" style="--pad-color:${detail?.color||CUE_COLORS[j]}" aria-label="DECK ${letter} ${d.padMode==='cue'?`ホットキュー${j+1} ${val==null?'設定':'再生'}`:d.padMode==='roll'?`${roll}拍ロール`:`${jump}拍ジャンプ`}" ${!t?'disabled':''}><strong>${d.padMode==='cue'?String.fromCharCode(65+j):d.padMode==='roll'?roll:jump}</strong><span>${d.padMode==='cue'?val==null?'＋':detail?.type==='loop'?'↻ '+time(val):time(val):'BEATS'}</span></button>`;}).join('')}</div>`,
fx:`<div class="deck-fx"><label>FX <select data-param="fx.type" data-deck="${i}" aria-label="DECK ${letter} エフェクト">${['echo','reverb','flanger'].map(x=>`<option ${d.fx.type===x?'selected':''} value="${x}">${x.toUpperCase()}</option>`).join('')}</select></label><input type="range" data-param="fx.mix" data-deck="${i}" data-map="deck.${i}.fx" min="0" max="1" step=".01" value="${d.fx.mix}" aria-label="DECK ${letter} FX量"><select data-param="fx.beats" data-deck="${i}" aria-label="エコー拍数">${[.125,.25,.5,1,2,4].map(v=>`<option value="${v}" ${d.fx.beats===v?'selected':''}>${v}拍</option>`).join('')}</select><label class="key-shift-label">KEY <input type="number" min="-12" max="12" step="1" value="${d.pitch}" data-param="pitch" data-deck="${i}" data-map="deck.${i}.pitch" aria-label="DECK ${letter} キーシフト半音"></label></div>`,
jog:`<div class="jog" data-jog="${i}" data-map="deck.${i}.jog" role="slider" aria-label="DECK ${letter} ジョグ。左右矢印でシーク" aria-valuemin="0" aria-valuemax="${t?.duration||0}" aria-valuenow="${d.position}" tabindex="0"><div class="jog-ring"></div><div class="jog-tick" data-jog-tick="${i}"></div><div class="jog-center"><span class="jog-mode">VINYL</span><span class="jog-time mono" data-time="${i}">${time(d.position)}</span><span class="jog-remaining mono" data-remaining="${i}">−${time((t?.duration||0)-d.position)}</span></div></div>`,
play:`<button data-action="cue" data-deck="${i}" data-map="deck.${i}.cue" class="cue-button" ${!t?'disabled':''}>CUE</button><button data-action="play" data-deck="${i}" data-map="deck.${i}.play" class="play-button ${d.playing?'active':''}" aria-label="DECK ${letter} ${d.playing?'一時停止':'再生'}" aria-pressed="${d.playing}" ${!t?'disabled':''}>${d.playing?icons.pause:icons.play}</button>`,
sync:`<button data-action="sync" data-deck="${i}" data-map="deck.${i}.sync" class="sync-button ${d.syncEnabled?'active':''}" aria-pressed="${!!d.syncEnabled}" title="MASTERに継続同期" ${!t?'disabled':''}>SYNC</button>`,
master:`<button data-action="select-deck" data-deck="${i}" class="master-button ${s.selectedDeck===i?'active':''}" aria-pressed="${s.selectedDeck===i}">MASTER</button>`,
pitch:`<div class="pitch-control"><label for="rate-${i}">TEMPO <output data-value="deck.${i}.rate">${((d.rate-1)*100).toFixed(2)}%</output></label><input id="rate-${i}" type="range" min=".5" max="1.5" step=".0001" value="${clamp(d.rate,.5,1.5)}" data-param="rate" data-deck="${i}" data-map="deck.${i}.rate" aria-label="DECK ${letter} テンポ"><div class="nudge-controls"><button data-nudge="-1" data-deck="${i}" title="押している間テンポを下げる">−</button><button data-action="rate-reset" data-deck="${i}">RESET</button><button data-nudge="1" data-deck="${i}" title="押している間テンポを上げる">＋</button></div></div>`
};
if(landscape)return landscapeDeck(i,s,t,parts);
 return `<div class="deck-inner" data-deck="${i}">${parts.track}${parts.data}${parts.overview}<div class="deck-performance">${parts.jog}<div class="transport"><div class="transport-row">${parts.play}</div><div class="transport-row">${parts.sync}${parts.master}</div>${parts.pitch}</div></div>${parts.options}${parts.loop}${parts.padTabs}${parts.pads}${parts.fx}</div>`;
}
function landscapeDeck(i,s,t,p){
 const surface=s.mobile.surfaces[i],letter=LETTERS[i];
 const track=`<div class="deck-track"><div class="deck-identity"><span class="deck-letter">${letter}</span><div><h3 title="${esc(t?.name||'音源をロード')} · ${esc(t?.artist||'')}">${esc(t?.name||'音源をロード')}</h3><p><span data-bpm="${i}" class="mono">${t?.samplePending?'未解析':t?Number(t.bpm*s.decks[i].rate).toFixed(1):'—'}</span> BPM <span class="touch-key">${esc(t?.key||'—')}</span></p></div></div><button class="deck-load" data-action="browse-deck" data-deck="${i}" aria-label="DECK ${letter}の曲を選ぶ">${icons.folder}</button></div>`;
 const content=surface==='vinyl'?`<div class="touch-vinyl">${p.jog}<div class="touch-loop">${p.loop}</div></div>`:surface==='pads'?`${p.padTabs}${p.pads}`:`${p.data}${p.pitch}${p.master}${p.options}${p.loop}${p.fx}`;
 return `<div class="deck-inner landscape-deck" data-deck="${i}" data-surface="${surface}">${track}${p.overview}<div class="touch-surface">${content}</div><div class="touch-deck-tabs" role="group" aria-label="DECK ${letter}の操作パネル">${[['vinyl','JOG'],['pads','PADS'],['tools','FX / TEMPO']].map(([v,label])=>`<button data-mobile-surface="${v}" data-deck="${i}" aria-pressed="${surface===v}">${label}</button>`).join('')}</div><div class="touch-transport">${p.play}${p.sync}</div></div>`;
}
function knob(i,name,label,min=-30,max=12){const d=i.deck,value=d[name],key=`deck.${i.index}.${name}`,angle=(value-min)/(max-min)*270-135;return `<label class="knob" style="--angle:${angle}deg" title="DECK ${LETTERS[i.index]} ${label}（ダブルクリックでリセット）"><span class="knob-face"><i></i></span><input type="range" data-param="${name}" data-deck="${i.index}" data-map="${key}" min="${min}" max="${max}" step="${name==='filter'?'.01':'.1'}" value="${value}" aria-label="DECK ${LETTERS[i.index]} ${label}"><span class="knob-caption">${label} <output data-value="${key}">${value.toFixed(name==='filter'?2:1)}</output></span></label>`;}
export function mixerMarkup(s){const indices=[0,1,2,3];return `<div class="mixer-inner"><div class="mixer-channels" style="--channels:${indices.length}">${indices.map(i=>{const d=s.decks[i];return `<div class="channel-strip" data-channel="${i}" style="--accent:${COLORS[i]}"><div class="channel-name"><span>${LETTERS[i]}</span><select data-param="assign" data-deck="${i}" aria-label="DECK ${LETTERS[i]} クロスフェーダー割当">${['A','THRU','B'].map(x=>`<option ${d.assign===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="eq-controls">${[['gain','TRIM',-24,12],['high','HI',-30,12],['mid','MID',-30,12],['low','LOW',-30,12]].map(([k,l,min,max])=>knob({deck:d,index:i},k,l,min,max)).join('')}</div><div class="filter-control">${knob({deck:d,index:i},'filter','FILTER',-1,1)}</div><button class="headphone-button ${d.cueOn?'active':''}" data-action="toggle" data-param="cueOn" data-deck="${i}" data-map="deck.${i}.cueOn" aria-pressed="${d.cueOn}" aria-label="DECK ${LETTERS[i]} ヘッドホンCUE">${icons.headphones}<span>CUE</span></button><div class="fader-area"><span class="fader-scale">0<br>−6<br>−12<br>−∞</span><input class="channel-fader" type="range" min="0" max="1" step=".001" value="${d.volume}" data-param="volume" data-deck="${i}" data-map="deck.${i}.volume" aria-label="DECK ${LETTERS[i]} チャンネル音量"><div class="level-meter"><i data-meter="${i}"></i></div></div></div>`;}).join('')}</div>
 <div class="crossfader-block"><div><span style="color:var(--a)">A</span><label for="crossfader">CROSSFADER</label><span style="color:var(--b)">B</span></div><input id="crossfader" type="range" min="-1" max="1" step=".001" value="${s.mixer.crossfader}" data-mixer="crossfader" data-map="mixer.crossfader" aria-label="クロスフェーダー"><div class="crossfader-ticks"><span>Ⅰ</span><button data-action="center-crossfader">CENTER</button><span>Ⅰ</span></div></div>
 <div class="master-output"><label for="master-volume">MASTER <output data-master-peak class="mono">−∞ dB</output></label><div class="master-level"><input id="master-volume" type="range" min="0" max="1" step=".001" value="${s.mixer.master}" data-mixer="master" data-map="mixer.master" aria-label="マスター音量"><div class="master-meter"><i data-master-meter></i></div></div></div></div>`;}
export function wavesMarkup(s){return `<div class="wave-stack">${s.decks.map((d,i)=>`<div class="wave-lane" data-wave-lane="${i}" ${!s.layout[`deck${i}`].visible?'hidden':''} style="--accent:${COLORS[i]}"><span class="wave-letter">${LETTERS[i]}</span><canvas data-wave="${i}" aria-label="DECK ${LETTERS[i]} 拡大波形" tabindex="0"></canvas><span class="wave-bpm mono" data-wave-bpm="${i}">—</span></div>`).join('')}</div>`;}
export function samplerMarkup(s,tracks){return `<div class="sampler-inner"><div class="sampler-pads">${s.sampler.map((p,i)=>`<button class="sample-pad ${p?'loaded':''}" data-sample="${i}" data-map="sampler.${i}" aria-label="サンプル${i+1} ${p?'再生':'設定'}"><span class="sample-number">${String(i+1).padStart(2,'0')}</span><strong>${esc(p?.label||'＋ SAMPLE')}</strong><small>${p?`${p.duration.toFixed(1)}s ${p.loop?'↻ LOOP':''}`:'選択デッキから切り出す'}</small></button>`).join('')}</div><div class="sample-volume"><label for="sampler-level">LEVEL</label><input id="sampler-level" type="range" min="0" max="1" step=".01" data-mixer="sampler" data-map="mixer.sampler" value="${s.mixer.sampler}" aria-label="サンプラー音量"><button data-action="stop-samples">STOP</button></div><button class="touch-only sample-edit" data-action="sample-edit" aria-pressed="false">パッドを編集</button><p class="sampler-hint">音源をドロップして割当 · Shift＋クリックで編集</p></div>`;}
export function libraryMarkup(s,tracks){return `<div class="library-inner"><aside class="crates" aria-label="クレート"><div class="crate-label">COLLECTION</div><button data-playlist="all" class="${s.playlist==='all'?'active':''}">${icons.folder}すべての音源 <span>${tracks.size}</span></button><button data-playlist="favorites" class="${s.playlist==='favorites'?'active':''}">☆ お気に入り</button><button data-playlist="history" class="${s.playlist==='history'?'active':''}">◷ プレイ履歴</button><div class="crate-label">CRATES <button data-action="new-playlist" aria-label="クレートを追加">＋</button></div>${s.playlists.map(p=>`<button data-playlist="${esc(p.id)}" class="${s.playlist===p.id?'active':''}" title="${esc(p.name)}">${icons.folder}${esc(p.name)}<span>${p.tracks.length}</span></button>`).join('')}<button class="crate-import" data-action="import">＋ 音源を追加</button></aside><div class="library-browser"><div class="library-search"><label><span aria-hidden="true">⌕</span><input type="search" id="track-search" placeholder="曲名、アーティスト、BPM、キーを検索" aria-label="ライブラリを検索"></label><button data-action="track-edit" class="button subtle">曲情報</button><button data-action="library-menu" class="button icon-button" aria-label="ライブラリ操作">···</button></div><div class="track-table-scroll"><table class="track-table"><thead><tr><th class="track-number">#</th><th><button data-sort="name">TRACK / ARTIST</button></th><th><button data-sort="bpm">BPM</button></th><th><button data-sort="key">KEY</button></th><th><button data-sort="duration">TIME</button></th><th class="load-col">LOAD TO</th><th>☆</th></tr></thead><tbody id="track-rows"></tbody></table></div><div class="library-footer"><span id="track-count"></span><div class="header-spacer"></div><span>ドラッグでデッキへロード</span></div></div></div>`;}
export function trackRows(list,s){return list.map((t,i)=>`<tr data-track="${esc(t.id)}" draggable="true" tabindex="0" class="${s.selectedTrack===t.id?'selected':''}" aria-selected="${s.selectedTrack===t.id}"><td class="track-number mono">${String(i+1).padStart(2,'0')}</td><td class="track-title"><div><strong>${esc(t.name)}</strong>${t.demo?'<span class="demo-tag">DEMO</span>':t.bundled?'<span class="demo-tag">公開サンプル</span>':''}${t.missing?'<span class="danger">音源未登録</span>':''}</div><small>${esc(t.artist||'Unknown artist')}</small></td><td class="mono">${t.samplePending?'未解析':Number(t.bpm).toFixed(1)}${!t.samplePending&&t.bpmConfidence<50?'<span title="推定値。グリッドを確認してください"> ≈</span>':''}</td><td><span class="key-chip">${esc(t.key||'—')}</span></td><td class="mono muted">${t.samplePending?'未解析':time(t.duration)}</td><td class="load-col"><div>${LETTERS.map((letter,j)=>`<button data-load-track="${esc(t.id)}" data-deck="${j}" style="--accent:${COLORS[j]}" aria-label="${esc(t.name)}をDECK ${letter}へロード">${letter}</button>`).join('')}</div><button class="touch-only mobile-load" data-load-track="${esc(t.id)}" data-deck="${s.mobile.deck}" aria-label="${esc(t.name)}をDECK ${LETTERS[s.mobile.deck]}へロード">${LETTERS[s.mobile.deck]} へロード</button></td><td><button class="favorite ${t.rating>0?'active':''}" data-favorite="${esc(t.id)}" aria-label="${esc(t.name)}のお気に入り" aria-pressed="${t.rating>0}">${t.rating>0?'★':'☆'}</button></td></tr>`).join('')||'<tr><td colspan="7" class="library-empty">該当する音源はありません。音源を追加するか、検索条件を変更してください。</td></tr>';}
export function dialogFrame(title,body){return `<div class="dialog-head"><h2>${esc(title)}</h2><div class="header-spacer"></div><button class="button icon-button" data-action="close-dialog" aria-label="閉じる">×</button></div><div class="dialog-body">${body}</div>`;}
